// Engenharia de Software — banco de questões, flashcards e discursivas
// Em QUESTOES a alternativa correta é SEMPRE a primeira (o app embaralha).
const TEMAS = {
  fu: "Fundamentos e princípios",
  ci: "Modelos de ciclo de vida",
  rq: "Requisitos, UML e especificação",
  ag: "Métodos ágeis (Scrum, XP, Kanban)",
  ar: "Arquiteturas de software",
  te: "Testes e TDD",
};

const QUESTOES = [
  // ======================= FUNDAMENTOS =======================
  { t: "fu", q: "Segundo o IEEE, engenharia de software é:", o: ["A aplicação de uma abordagem sistemática, disciplinada e quantificável no desenvolvimento, na operação e na manutenção de software", "A atividade de escrever código o mais rápido possível", "O conjunto de linguagens de programação usadas em um projeto", "A gestão do hardware em que o software roda"], e: "Definição do IEEE: abordagem sistemática, disciplinada e quantificável no desenvolvimento, operação e manutenção — ou seja, a aplicação de engenharia ao software." },
  { t: "fu", q: "Qual é a “pedra fundamental” que sustenta a engenharia de software?", o: ["O foco na qualidade", "A escolha da linguagem", "O número de desenvolvedores", "O orçamento do projeto"], e: "Na visão em camadas, o foco na qualidade é a base de tudo; acima dele vêm processos, métodos e ferramentas." },
  { t: "fu", q: "Qual camada é a “liga” que mantém as camadas de tecnologia coesas e permite desenvolver de forma racional e no prazo?", o: ["A camada de processos", "A camada de ferramentas", "A camada de hardware", "A camada de interface"], e: "A base da engenharia de software é a camada de processos: ela une métodos e ferramentas e permite o desenvolvimento racional e dentro do prazo." },
  { t: "fu", q: "A essência da prática da engenharia de software segue qual sequência?", o: ["Compreender o problema → planejar a solução → executar o plano → examinar o resultado", "Codificar → testar → planejar → compreender", "Planejar → codificar → entregar → documentar", "Testar → codificar → compreender → entregar"], e: "Compreender (comunicação e análise), planejar (modelagem e projeto), executar (geração de código) e examinar (testes e garantia da qualidade)." },
  { t: "fu", q: "Na essência da prática, “examinar o resultado para ter precisão” corresponde a:", o: ["Testes e garantia da qualidade", "Comunicação e análise", "Modelagem e projeto", "Geração de código"], e: "Examinar o resultado = testes + garantia da qualidade (SQA)." },
  { t: "fu", q: "Na essência da prática, “planejar uma solução” corresponde a:", o: ["Modelagem e projeto de software", "Geração de código", "Testes", "Implantação"], e: "Planejar a solução = modelagem e projeto. Compreender = comunicação e análise; executar = código; examinar = testes." },
  { t: "fu", q: "Qual é o 1º princípio de Hooker, no qual todos os outros se apoiam?", o: ["A razão de existir: o software existe para agregar valor aos usuários", "KISS: mantenha simples", "Pense!", "Planeje visando a reutilização"], e: "“Isso realmente agrega valor real ao sistema?” Se a resposta for não, não faça. Todos os outros princípios se apoiam neste." },
  { t: "fu", q: "O princípio KISS diz que o projeto deve ser:", o: ["O mais simples possível, mas não simplista", "O mais completo possível, mesmo que complexo", "Feito sem documentação", "Escrito em uma única classe"], e: "KISS (Keep It Simple, Stupid!): simples, mas não simplista. Projetos simples são mais fáceis de manter e menos propensos a erros." },
  { t: "fu", q: "O princípio “mantenha a visão” alerta contra:", o: ["Transformar o projeto em uma colcha de retalhos sem integridade conceitual", "Usar muitos testes automatizados", "Reutilizar código", "Conversar com o cliente"], e: "Sem integridade conceitual, o sistema vira uma colcha de retalhos de projetos incompatíveis; comprometer a visão arquitetural pode destruir sistemas bem projetados." },
  { t: "fu", q: "“O que um produz, outros consomem” significa:", o: ["Especificar, projetar, documentar e codificar sabendo que outra pessoa terá de entender e manter aquilo", "Que o cliente deve pagar por cada entrega", "Que todo código deve ser open source", "Que os testes são feitos por outra equipe"], e: "Alguém vai depurar, manter e ampliar o que você fez — isso torna essa pessoa usuária do seu código." },
  { t: "fu", q: "O princípio “esteja aberto para o futuro” recomenda:", o: ["Projetar o sistema para se adaptar a mudanças, perguntando sempre “e se…?”", "Congelar os requisitos no início", "Evitar qualquer mudança após a entrega", "Usar sempre a tecnologia mais nova"], e: "Tudo muda em meses, não anos. Sistemas de qualidade industrial devem durar e estar prontos para se adaptar — jamais faça projetos limitados." },
  { t: "fu", q: "Segundo o 6º princípio, qual é “indiscutivelmente a meta mais difícil” no desenvolvimento?", o: ["Alcançar um alto grau de reutilização", "Escrever a documentação", "Escolher o banco de dados", "Fazer a entrevista com o cliente"], e: "Planejar a reutilização com antecedência reduz custo e aumenta valor, mas atingir alta reutilização é a meta mais difícil." },
  { t: "fu", q: "Um efeito colateral positivo do 7º princípio (“Pense!”) é:", o: ["Aprender a reconhecer quando não se sabe algo", "Eliminar a necessidade de testes", "Dispensar o cliente das reuniões", "Programar sem planejar"], e: "Pensar com clareza antes de agir produz melhores resultados e ensina a reconhecer o que não se sabe e até onde buscar o conhecimento." },
  { t: "fu", q: "Quantos são os princípios gerais de Hooker?", o: ["7", "4", "5", "12"], e: "Sete: razão de existir, KISS, mantenha a visão, o que um produz outros consomem, aberto para o futuro, planeje a reutilização e pense." },
  { t: "fu", q: "Todo projeto de software é motivado por:", o: ["Alguma necessidade de negócio", "A vontade de usar uma nova linguagem", "A existência de um framework", "Uma exigência do hardware"], e: "Corrigir defeito, adaptar sistema legado, ampliar funções ou criar um novo produto — sempre uma necessidade de negócio." },
  { t: "fu", q: "Um processo de software é:", o: ["Um conjunto estruturado de atividades e práticas para desenvolver, manter e entregar software de forma sistemática", "Um programa em execução no sistema operacional", "Uma linguagem de modelagem", "Um tipo de teste automatizado"], e: "O processo define como o trabalho será feito, quem fará, quando e com quais recursos — um roteiro previsível." },
  { t: "fu", q: "Por que o processo de software é importante?", o: ["Propicia estabilidade, controle e organização a uma atividade que pode ficar caótica", "Elimina a necessidade de clientes", "Garante que o software nunca terá defeitos", "Substitui a programação"], e: "O processo dá estabilidade, controle e organização. E o processo adequado depende do software: avião ≠ app móvel ≠ videogame." },
  { t: "fu", q: "No caso Winburg, qual foi um motivo central do fracasso?", o: ["Requisitos não funcionais críticos (precisão ≥ 98% e resposta < 1 s) não foram atendidos nem testados", "A linguagem escolhida era antiga", "O sistema aceitava cartão de crédito", "Faltaram ônibus na cidade"], e: "O reconhecimento de cédulas não chegou a 98% e demorava mais de 1 s: filas, cédulas válidas recusadas, papel falso aceito e falta de testes rigorosos." },
  { t: "fu", q: "No caso Winburg, aceitar papel falso como cédula é um:", o: ["Falso positivo, que leva à perda de receita", "Falso negativo, que afasta usuários", "Requisito funcional atendido", "Erro de usabilidade apenas"], e: "Falso positivo = aceitar o que não devia (perda de receita). Falso negativo = rejeitar cédula válida (afasta usuários)." },
  { t: "fu", q: "Qual lição principal o caso Winburg ensina?", o: ["Requisitos não funcionais (desempenho, precisão) podem decidir o sucesso do sistema e precisam ser testados antes da implantação", "Software de transporte não precisa de testes", "Requisitos funcionais são os únicos que importam", "Basta o sistema compilar para ser entregue"], e: "O sistema não equilibrou eficiência, segurança e usabilidade — houve rejeição pelos usuários e fracasso operacional e financeiro." },

  // ======================= CICLO DE VIDA =======================
  { t: "ci", q: "Por que existem modelos de processo (ciclos de vida)?", o: ["Para organizar, orientar e sistematizar o desenvolvimento, com planejamento, controle e redução de riscos", "Para substituir os programadores", "Para eliminar a documentação", "Para obrigar o uso de uma linguagem"], e: "Eles estruturam o trabalho, facilitam planejamento e controle, reduzem riscos, melhoram a comunicação e se adaptam a contextos diferentes." },
  { t: "ci", q: "O modelo cascata é indicado quando:", o: ["Os requisitos são bem compreendidos e estáveis", "Os requisitos mudam toda semana", "O cliente não sabe o que quer", "O projeto tem altíssimo risco técnico"], e: "Cascata (sequencial linear): cada fase depende da anterior. Ideal com requisitos estáveis, poucas mudanças e muita documentação." },
  { t: "ci", q: "Qual é um ponto fraco do modelo cascata?", o: ["Validação tardia: o cliente só vê o produto funcionando no final", "Excesso de protótipos", "Falta total de documentação", "Entregas a cada duas semanas"], e: "Pontos fracos: pouca flexibilidade, dependência de documentação, validação tardia e risco de desalinhamento com o cliente." },
  { t: "ci", q: "Qual é um ponto forte do modelo cascata?", o: ["Rigor, previsibilidade e facilidade de gestão, úteis em ambientes regulados", "Aceitar mudanças a qualquer momento", "Entregar software em sprints curtas", "Dispensar documentação"], e: "Pontos fortes: rigor e disciplina, gestão fácil, controle de qualidade por fase (SQA) e previsibilidade." },
  { t: "ci", q: "Modelos prescritivos também são chamados de:", o: ["Tradicionais ou clássicos", "Ágeis", "Exploratórios", "Reativos"], e: "Prescritivos = tradicionais/clássicos: prescrevem atividades, artefatos e controles de forma ordenada e sequencial." },
  { t: "ci", q: "Qual modelo é uma extensão do cascata que enfatiza verificação e validação em cada etapa?", o: ["Modelo V", "Espiral", "RAD", "Kanban"], e: "No Modelo V, cada fase de desenvolvimento tem uma fase de teste correspondente (verificação e validação)." },
  { t: "ci", q: "O modelo incremental:", o: ["Entrega o software em partes (incrementos), adicionando funcionalidades a cada entrega", "Entrega tudo de uma vez no final", "Não permite entregas parciais", "É sinônimo de codificar-e-corrigir"], e: "Melhoria do cascata: em vez de tudo de uma vez, entrega pequenos pedaços, aplicando o cascata de forma iterativa com refinamentos sucessivos." },
  { t: "ci", q: "Os modelos evolucionários incluem:", o: ["Espiral e prototipação", "Cascata e Modelo V", "Scrum e XP", "MVC e MVVM"], e: "Modelos evolucionários permitem que o software evolua com o tempo: espiral e prototipação." },
  { t: "ci", q: "O modelo RAD (Rapid Application Development) foca em:", o: ["Velocidade, prototipação rápida e entregas rápidas", "Análise de riscos antes de cada fase", "Documentação extensa", "Desenvolvimento por voluntários"], e: "RAD = foco em velocidade e protótipos, com entregas rápidas." },
  { t: "ci", q: "O modelo espiral é baseado em:", o: ["Ciclos com análise de riscos antes de cada fase", "Uma única passagem sequencial", "Desenvolvimento voluntário", "Sincronização diária de equipes"], e: "Espiral = cascata em que cada fase é precedida por análise de riscos. Se os riscos não puderem ser minimizados, o projeto pode ser encerrado." },
  { t: "ci", q: "No modelo espiral, o que representa a dimensão radial?", o: ["O custo acumulado até então", "O número de programadores", "A quantidade de requisitos", "O tempo de cada sprint"], e: "Dimensão radial = custo acumulado; dimensão angular = progresso ao longo da espiral. Cada ciclo é uma fase." },
  { t: "ci", q: "No espiral, se um risco significativo não puder ser minimizado:", o: ["O projeto pode ser encerrado imediatamente (ou seguir em escala bem menor)", "O risco é ignorado", "O cliente é trocado", "Passa-se direto para a implantação"], e: "Antes de cada fase tenta-se controlar os riscos (às vezes com protótipo). Se impossível, o projeto é interrompido ou reduzido." },
  { t: "ci", q: "Um protótipo rápido é:", o: ["Um modelo operacional funcionalmente equivalente a um subconjunto do produto", "O produto final completo", "Apenas um desenho de tela em papel", "O documento de especificação"], e: "Ex.: para contas a pagar/receber e estoque, o protótipo captura dados na tela e imprime relatórios, mas não atualiza arquivos nem trata erros." },
  { t: "ci", q: "Por que a prototipagem rápida tende a precisar de menos “voltas” de realimentação que o cascata?", o: ["Porque a especificação é escrita a partir de um protótipo já validado pelo cliente", "Porque não há especificação", "Porque não há testes", "Porque o cliente não participa"], e: "O cliente interage com o protótipo; quando ele está satisfeito, a equipe redige a especificação com a certeza de atender às necessidades reais." },
  { t: "ci", q: "No ciclo de vida de software aberto, portar o programa para um novo ambiente é manutenção:", o: ["Adaptativa", "Corretiva", "De aperfeiçoamento", "Preventiva"], e: "Corretiva = corrigir defeitos; de aperfeiçoamento = acrescentar funcionalidade; adaptativa = portar para novo ambiente." },
  { t: "ci", q: "No software aberto, acrescentar funcionalidade extra é manutenção:", o: ["De aperfeiçoamento", "Corretiva", "Adaptativa", "Emergencial"], e: "Aperfeiçoamento (perfectiva) = novas funcionalidades. Corretiva = defeitos. Adaptativa = novo ambiente." },
  { t: "ci", q: "Quais são as duas fases informais de um projeto open source bem-sucedido?", o: ["1) um indivíduo cria e distribui uma versão inicial; 2) usuários viram codesenvolvedores", "1) contrato com o cliente; 2) entrega final", "1) análise de riscos; 2) protótipo", "1) sprint planning; 2) retrospectiva"], e: "Ex.: Linux, Firefox, Apache. Na fase 2 usuários relatam defeitos, sugerem correções, estendem funções e portam o programa." },
  { t: "ci", q: "No modelo de software aberto, os participantes normalmente:", o: ["Trabalham de forma voluntária, no tempo livre, com um grupo central de mantenedores", "São todos funcionários pagos de uma empresa", "Não podem relatar defeitos", "Seguem sprints de 4 semanas"], e: "Há um grupo central (gerencia e garante as correções) e um grupo periférico (relata defeitos de vez em quando)." },
  { t: "ci", q: "O software aberto tem características em comum com quais modelos?", o: ["Codificar-e-corrigir e prototipagem rápida (todos geram logo uma versão operacional)", "Cascata e Modelo V", "Espiral e RAD", "Scrum e Kanban"], e: "Nos três é produzida uma versão inicial operacional logo no começo." },
  { t: "ci", q: "O modelo sincronizar-e-estabilizar é associado a qual empresa?", o: ["Microsoft", "Google", "Apple", "IBM"], e: "A Microsoft, maior fabricante de software COTS, usa essa versão do modelo iterativo e incremental (Cusumano e Selby, 1997)." },
  { t: "ci", q: "No sincronizar-e-estabilizar, o que acontece no fim de cada dia?", o: ["As equipes juntam os componentes, testam e depuram o produto (sincronizam)", "O projeto é congelado", "O cliente aprova o contrato", "Faz-se a análise de riscos"], e: "Sincronização frequente garante que os componentes sempre funcionem juntos. A estabilização (correção e congelamento) ocorre no fim de cada incorporação." },
  { t: "ci", q: "No sincronizar-e-estabilizar, a primeira incorporação contém:", o: ["Os recursos mais fundamentais (de maior prioridade)", "Apenas a interface gráfica", "Todos os recursos de uma vez", "Somente os testes"], e: "O trabalho é dividido em 3 ou 4 incorporações, por ordem de prioridade, feitas por pequenas equipes em paralelo." },

  // ======================= REQUISITOS =======================
  { t: "rq", q: "Qual é o objetivo real do levantamento de necessidades?", o: ["Determinar qual software o cliente precisa", "Escolher a linguagem de programação", "Escrever o código-fonte", "Definir o preço do produto"], e: "Levantamento de necessidades = descobrir o que o cliente realmente precisa." },
  { t: "rq", q: "Qual é a primeira etapa do levantamento de necessidades?", o: ["Adquirir conhecimento do campo de aplicação (domínio)", "Escrever os casos de teste", "Construir o banco de dados", "Implantar o sistema"], e: "Primeiro entende-se o ambiente em que o produto vai operar; depois constrói-se o modelo de negócio." },
  { t: "rq", q: "Um modelo de negócio é:", o: ["Uma descrição dos processos de negócio de uma organização", "O plano financeiro da empresa de software", "O código-fonte do sistema", "A lista de bugs"], e: "Ex.: num banco, depósitos, empréstimos e investimentos. Gera um entendimento do negócio do cliente como um todo; é descrito com diagramas UML." },
  { t: "rq", q: "Qual a diferença entre levantamento e análise de necessidades?", o: ["Levantamento descobre o conjunto preliminar; análise refina e estende esse conjunto", "São sinônimos exatos", "Análise vem antes do levantamento", "Levantamento é feito só após a codificação"], e: "Levantamento (captura) descobre as necessidades; a análise de requisitos refina e estende o conjunto preliminar." },
  { t: "rq", q: "Uma entrevista estruturada:", o: ["Usa perguntas específicas, planejadas com antecedência, normalmente fechadas", "Não tem nenhuma pergunta preparada", "É feita só por e-mail", "Dispensa relatório"], e: "Na entrevista livre, as perguntas seguintes surgem em resposta ao que o entrevistado diz." },
  { t: "rq", q: "Em uma entrevista livre:", o: ["As perguntas seguintes são feitas em resposta ao que o entrevistado fala", "Todas as perguntas são fechadas e planejadas", "O entrevistado não pode falar livremente", "Não há entrevistador"], e: "Pode começar com uma ou duas perguntas fechadas, mas depois segue o rumo da conversa." },
  { t: "rq", q: "O que é necessário para registrar em vídeo o trabalho dos funcionários do cliente?", o: ["Autorização por escrito das pessoas observadas", "Nada, basta instalar a câmera", "Autorização verbal do gerente de TI", "Que o vídeo seja público"], e: "A versão moderna da observação direta usa câmeras, sempre com autorização por escrito de quem é observado." },
  { t: "rq", q: "Após uma entrevista, o recomendado é:", o: ["Escrever um relatório e dar uma cópia ao entrevistado para ele esclarecer ou complementar", "Descartar as anotações", "Começar a codificar imediatamente", "Enviar o relatório só ao gerente"], e: "O entrevistado pode querer esclarecer afirmações ou acrescentar pontos não considerados." },
  { t: "rq", q: "Em um diagrama de caso de uso, o ator é:", o: ["Um membro do mundo externo ao produto de software (frequentemente um usuário)", "Uma classe interna do sistema", "O banco de dados", "O retângulo do diagrama"], e: "O ator (boneco de palito) desempenha um papel em relação ao produto; o retângulo representa o produto de software." },
  { t: "rq", q: "No exemplo bancário de caso de uso, quais são os atores e o caso de uso?", o: ["Customer e Teller; caso de uso Withdraw Money (saque)", "Bank e ATM; caso de uso Deposit", "Manager e Database; caso de uso Login", "Cliente e Servidor; caso de uso Transferir"], e: "Dois atores (cliente e caixa de banco) e a oval “Withdraw Money” (saque de dinheiro)." },
  { t: "rq", q: "No diagrama de caso de uso, o retângulo representa:", o: ["O produto de software (fronteira do sistema)", "Um ator", "Um requisito não funcional", "Uma classe"], e: "O caso de uso mostra a interação entre o produto (retângulo) e o ambiente em que ele opera (atores)." },
  { t: "rq", q: "Qual é uma vantagem dos diagramas UML?", o: ["Melhoram a comunicação, inclusive com pessoas não técnicas", "Eliminam a necessidade de testes", "Geram o sistema pronto automaticamente", "Substituem o cliente"], e: "UML simplifica a complexidade, padroniza a comunicação, ajuda no design antes da implementação e documenta o sistema." },
  { t: "rq", q: "O documento de especificação é:", o: ["Um contrato entre cliente e desenvolvedor que especifica o que o produto deve fazer e suas restrições", "Um manual de instalação", "O código-fonte comentado", "A ata da daily"], e: "Ele diz precisamente o que o produto deve fazer e quais restrições deve respeitar." },
  { t: "rq", q: "Qual é um componente vital do documento de especificação?", o: ["Os critérios de aceitação", "O logotipo da empresa", "A lista de linguagens", "O organograma"], e: "Critérios de aceitação = testes que provam ao cliente que o produto atende à especificação e que o trabalho está feito." },
  { t: "rq", q: "Requisitos funcionais descrevem:", o: ["O QUE o sistema faz (ações e operações visíveis ao usuário)", "COMO o sistema faz (qualidade e restrições)", "O orçamento", "O hardware do servidor"], e: "RF: login, cadastro (CRUD), pagamento, pesquisa de produtos, histórico de pedidos…" },
  { t: "rq", q: "Requisitos não funcionais descrevem:", o: ["COMO o sistema faz: atributos de qualidade e restrições", "Quais telas existem", "Quais botões o usuário clica", "A lista de casos de uso"], e: "RNF (atributos de qualidade): desempenho, usabilidade, segurança, confiabilidade, escalabilidade, portabilidade. Influenciam a arquitetura." },
  { t: "rq", q: "“O sistema deve processar uma transação em menos de 3 segundos” é um RNF de:", o: ["Desempenho", "Portabilidade", "Usabilidade", "Funcionalidade"], e: "Tempo de resposta/carregamento é desempenho. Outro exemplo: página principal em no máximo 1 s." },
  { t: "rq", q: "“O sistema deve estar disponível 99,9% do tempo” é um RNF de:", o: ["Confiabilidade", "Escalabilidade", "Segurança", "Usabilidade"], e: "Confiabilidade inclui disponibilidade e recuperação sem perda de dados após falha de energia." },
  { t: "rq", q: "“O sistema deve suportar mil usuários simultâneos sem degradação” é um RNF de:", o: ["Escalabilidade", "Portabilidade", "Usabilidade", "Confiabilidade"], e: "Escalabilidade: aguentar mais carga e permitir adicionar servidores para aumentar a capacidade." },
  { t: "rq", q: "“O app deve ser compatível com as versões recentes de Android e iOS” é um RNF de:", o: ["Portabilidade", "Desempenho", "Segurança", "Confiabilidade"], e: "Portabilidade = rodar em diferentes plataformas/navegadores." },
  { t: "rq", q: "“As senhas dos usuários devem ser criptografadas” é um requisito:", o: ["Não funcional de segurança", "Funcional de login", "Não funcional de usabilidade", "Funcional de cadastro"], e: "Define uma restrição de qualidade (como a função deve ser feita), não uma função nova." },
  { t: "rq", q: "“O sistema deve permitir que o usuário pesquise produtos e filtre os resultados” é um:", o: ["Requisito funcional", "Requisito não funcional de desempenho", "Requisito não funcional de portabilidade", "Critério de arquitetura"], e: "É uma ação que o sistema deve suportar — o QUE ele faz." },

  // ======================= ÁGEIS =======================
  { t: "ag", q: "A filosofia ágil defende:", o: ["Satisfação do cliente, entrega incremental antecipada, equipes pequenas e motivadas e simplicidade", "Documentação extensa antes de qualquer código", "Equipes grandes e hierárquicas", "Entrega única no final do projeto"], e: "Também: métodos informais e artefatos mínimos. Os princípios priorizam a entrega mais do que a análise e o projeto." },
  { t: "ag", q: "Uma equipe ágil é:", o: ["Auto-organizada e controla seu próprio destino", "Comandada por um gerente que decide cada tarefa", "Formada apenas por programadores, sem cliente", "Sempre com mais de 20 pessoas"], e: "Engenheiros, gerentes, clientes e usuários trabalham juntos, acelerando comunicação e colaboração." },
  { t: "ag", q: "O desenvolvimento ágil poderia ser chamado de:", o: ["Engenharia de software light", "Engenharia sem processo", "Codificar-e-corrigir", "Cascata acelerado"], e: "As atividades básicas (comunicação, planejamento, modelagem, construção e entrega) continuam, mas como um conjunto mínimo de tarefas." },
  { t: "ag", q: "Qual é o artefato mais importante no ágil?", o: ["Um incremento de software operacional entregue na data combinada", "O documento de especificação completo", "O diagrama de Gantt", "O manual do usuário"], e: "Os documentos mais importantes são as histórias de usuário e os casos de teste relacionados." },
  { t: "ag", q: "Agilidade significa:", o: ["Adaptar-se rapidamente às mudanças, entregando valor contínuo e mantendo a qualidade", "Apenas programar mais rápido", "Não ter planejamento", "Eliminar os testes"], e: "Envolve velocidade, adaptação, qualidade e colaboração. Não é só ser rápido." },
  { t: "ag", q: "Qual é uma característica de um processo ágil?", o: ["Mudanças nos requisitos são bem-vindas, mesmo em estágios avançados", "Os requisitos são congelados no início", "O cliente só participa na entrega", "Não há reuniões"], e: "Iterativo/incremental, flexível, foco no cliente, colaboração (dailies), entrega contínua e melhoria contínua." },
  { t: "ag", q: "No Scrum, a janela de tempo em que as tarefas são realizadas chama-se:", o: ["Sprint", "Release train", "Fase", "Milestone"], e: "Sprints duram de 2 a 4 semanas e geram um incremento." },
  { t: "ag", q: "Quem compõe o time Scrum?", o: ["Product Owner, Scrum Master e uma pequena equipe de desenvolvimento (3 a 6 pessoas)", "Gerente de projeto, analista e testador", "Cliente e 20 programadores", "Apenas o Scrum Master"], e: "Equipe interdisciplinar e auto-organizada." },
  { t: "ag", q: "Quais são os principais artefatos do Scrum?", o: ["Backlog do produto, backlog do sprint e incremento", "Documento de especificação, Gantt e WBS", "Cartões CRC e diagrama de classes", "Quadro Kanban e burndown apenas"], e: "Backlog do produto (tudo que agrega valor), backlog do sprint (o escolhido para o sprint) e o incremento de código." },
  { t: "ag", q: "Quem define a prioridade dos itens do backlog do produto?", o: ["O Product Owner", "O Scrum Master", "Cada desenvolvedor", "O cliente final, sem o PO"], e: "O PO ordena o backlog conforme os objetivos do projeto e define a meta do sprint." },
  { t: "ag", q: "Quem pode encerrar ou estender um sprint?", o: ["Somente o Product Owner", "Somente o Scrum Master", "Qualquer desenvolvedor", "O cliente"], e: "Pegadinha clássica: só o Product Owner pode encerrar ou estender um sprint." },
  { t: "ag", q: "A equipe de desenvolvimento pode adicionar novas tarefas no meio do sprint?", o: ["Não, sem cancelar ou reiniciar o sprint", "Sim, a qualquer momento", "Sim, se o Scrum Master aprovar", "Só às sextas-feiras"], e: "A equipe define como fazer e quando está pronto, mas não adiciona tarefas sem cancelar/reiniciar o sprint." },
  { t: "ag", q: "O backlog do produto:", o: ["Nunca está totalmente completo, pois o produto sempre evolui", "É fechado no primeiro dia e não muda", "É escrito apenas pelos desenvolvedores", "Só contém bugs"], e: "Pode ser atualizado a qualquer momento, com aprovação do PO e da equipe." },
  { t: "ag", q: "Qual é o papel do Scrum Master?", o: ["Facilitador: conduz a daily, remove obstáculos e ajuda o PO com o backlog", "Chefe que distribui ordens", "Dono do produto que prioriza o backlog", "Cliente que aprova as entregas"], e: "Ele orienta a equipe a colaborar e completar as tarefas." },
  { t: "ag", q: "Quanto dura a Daily Scrum?", o: ["15 minutos", "1 hora", "3 horas", "Um dia inteiro"], e: "Reunião rápida no início do dia para sincronizar e planejar as próximas 24 h." },
  { t: "ag", q: "Quais são as 3 perguntas da Daily Scrum?", o: ["O que fiz desde a última reunião? Que obstáculos enfrento? O que farei até a próxima?", "Quanto custa? Quem paga? Quando entrega?", "O que deu certo? O que melhorar? Com o que nos comprometemos?", "Qual linguagem? Qual banco? Qual servidor?"], e: "As perguntas “o que deu certo/melhorar/compromisso” são da retrospectiva, não da daily." },
  { t: "ag", q: "Quem participa obrigatoriamente da Daily Scrum?", o: ["O Scrum Master e a equipe de desenvolvimento", "Somente o Product Owner", "O cliente e o gerente", "Toda a empresa"], e: "O Product Owner pode participar ocasionalmente, se a equipe permitir." },
  { t: "ag", q: "Qual é a duração máxima da retrospectiva (sprint de 4 semanas)?", o: ["Até 3 horas", "15 minutos", "1 dia", "1 semana"], e: "É feita antes do próximo planejamento e liderada pelo Scrum Master." },
  { t: "ag", q: "Na Sprint Planning, quem define a meta do sprint?", o: ["O Product Owner", "O Scrum Master sozinho", "O cliente", "O testador"], e: "O PO define a meta; o SM e os devs selecionam os itens do backlog do sprint e planejam o trabalho." },
  { t: "ag", q: "As quatro atividades metodológicas do XP são:", o: ["Planejamento, projeto, codificação e testes", "Requisitos, análise, projeto e entrega", "Sprint, daily, review e retrospectiva", "Iniciação, elaboração, construção e transição"], e: "Cada atividade tem suas práticas: histórias, KISS/CRC, TDD/pares/CI, testes automatizados/aceitação." },
  { t: "ag", q: "No planejamento do XP, quem cria as histórias de usuário?", o: ["O cliente, priorizando pelo valor de negócio", "O Scrum Master", "Somente os testadores", "O arquiteto de software"], e: "A equipe atribui custo (em semanas) a cada história; após cada versão calcula-se a velocidade do projeto." },
  { t: "ag", q: "Qual prática pertence à atividade de PROJETO no XP?", o: ["Cartões CRC e refatoração contínua", "Programação em pares", "Testes de aceitação do cliente", "Daily de 15 minutos"], e: "Projeto no XP: KISS, cartões CRC, protótipos (spikes) para problemas difíceis e refatoração." },
  { t: "ag", q: "Qual prática pertence à atividade de CODIFICAÇÃO no XP?", o: ["Programação em pares, testes antes do código e integração contínua", "Cartões CRC", "Cálculo de velocidade", "Retrospectiva"], e: "Codificação XP: testes de unidade antes do código (TDD), pair programming e CI." },
  { t: "ag", q: "No XP, os testes de aceitação são definidos por:", o: ["O cliente", "O Scrum Master", "O compilador", "A equipe de infraestrutura"], e: "Garantem funcionalidades visíveis e valiosas. Os testes de unidade são automatizados e usados para regressão." },
  { t: "ag", q: "O Kanban é:", o: ["Um sistema visual em que as tarefas se movem por colunas de um quadro", "Um modelo de arquitetura", "Um framework de testes", "Um tipo de diagrama UML"], e: "Ex.: A fazer → Em andamento → Em teste → Feito. Gerencia o fluxo de trabalho." },
  { t: "ag", q: "Qual framework ágil é baseado em papéis (PO, SM, time), sprints e reuniões regulares?", o: ["Scrum", "Kanban", "XP", "RAD"], e: "Kanban = quadro visual; XP = práticas técnicas (testes automatizados, pares)." },

  // ======================= ARQUITETURAS =======================
  { t: "ar", q: "No MVC, qual camada contém as regras de negócio e o acesso a dados?", o: ["Model", "View", "Controller", "Adapter"], e: "Model = regras e dados; View = interface; Controller = recebe requisições e coordena Model e View." },
  { t: "ar", q: "No MVC, o Controller:", o: ["Recebe requisições, interpreta e coordena Model e View", "Desenha a interface", "Guarda os dados no banco", "É a camada de testes"], e: "O Controller é o “maestro” entre a requisição, o Model e a View." },
  { t: "ar", q: "Qual problema o MVC resolve?", o: ["Evita misturar lógica de negócio com lógica de interface", "Elimina a necessidade de banco de dados", "Torna o domínio independente de qualquer framework", "Faz data binding automático"], e: "Também facilita a manutenção da UI e permite equipes diferentes em partes distintas." },
  { t: "ar", q: "Qual é uma desvantagem típica do MVC?", o: ["Controllers que crescem demais (God Controllers)", "Não ter separação de responsabilidades", "Ser difícil de ensinar", "Falta de frameworks"], e: "Além disso, não escala bem para UIs muito ricas e perdeu espaço no front-end com as SPAs." },
  { t: "ar", q: "Qual conjunto de frameworks usa MVC no backend web?", o: ["Django, Ruby on Rails, Laravel, ASP.NET MVC, Spring MVC", "Angular, Vue, Knockout", "Quarkus, Micronaut, NestJS", "xUnit, JUnit, pytest"], e: "Desktop com MVC: Java Swing/SWT, .NET Windows Forms." },
  { t: "ar", q: "No MVVM, qual componente expõe dados e eventos reativos para a View?", o: ["ViewModel", "Controller", "Port", "Entity"], e: "A View se liga ao ViewModel por data binding (ligação automática)." },
  { t: "ar", q: "O mecanismo típico do MVVM é:", o: ["Data binding entre View e ViewModel", "Ports e adapters", "Regra de dependência para dentro", "God Controller"], e: "O binding reduz o código repetitivo de sincronização entre dados e interface." },
  { t: "ar", q: "Onde o MVVM se aplica melhor?", o: ["UIs complexas e muito interativas, apps mobile e SPAs", "CRUDs simples renderizados no servidor", "Scripts de linha de comando", "Bancos de dados"], e: "UIs com eventos constantes: animações, formulários dinâmicos, binding automático." },
  { t: "ar", q: "Qual é uma vantagem do MVVM?", o: ["Alta testabilidade, pois o ViewModel é só lógica", "Nenhuma curva de aprendizado", "Depuração sempre fácil", "Não precisa de View"], e: "View muito simples (quase só marcação), menos boilerplate, ótimo para experiências ricas." },
  { t: "ar", q: "Qual é uma desvantagem do MVVM?", o: ["O data binding pode dificultar a depuração", "Mistura regra de negócio com a View", "Não funciona em mobile", "Exige banco NoSQL"], e: "Também: sobrecarga mental para iniciantes e risco de ViewModels gigantes." },
  { t: "ar", q: "Quais tecnologias são associadas ao MVVM?", o: ["Angular, Vue, Knockout, Android ViewModel, SwiftUI, WPF, Flutter", "Rails, Laravel, Django", "JUnit, TestNG, RSpec", "Spring Boot, Quarkus, Micronaut"], e: "Desktop: WPF, WinUI, Qt (parcial), Avalonia. Cross-platform: Flutter (Provider, Riverpod, MobX)." },
  { t: "ar", q: "Arquitetura hexagonal também é chamada de:", o: ["Ports and Adapters", "Model–View–Controller", "Arquitetura em cascata", "Sincronizar-e-estabilizar"], e: "Separa o núcleo (domínio) das interfaces externas usando portas e adaptadores." },
  { t: "ar", q: "Na arquitetura hexagonal, os Ports são:", o: ["Interfaces que o domínio expõe ou de que precisa", "Implementações concretas de banco de dados", "Telas da aplicação", "Testes de integração"], e: "Adapters são as implementações que conectam o domínio ao mundo externo (bancos, APIs, UI, mensageria)." },
  { t: "ar", q: "Na arquitetura hexagonal, os Adapters:", o: ["Conectam o domínio ao mundo externo (banco, APIs, UI, mensageria)", "Contêm as regras de negócio centrais", "São as histórias de usuário", "Definem as sprints"], e: "Trocar o banco = trocar o adapter, sem mexer no domínio." },
  { t: "ar", q: "A arquitetura hexagonal se baseia em:", o: ["Forte desacoplamento e inversão de dependência", "Data binding", "Controllers centralizados", "Ausência de interfaces"], e: "Regras de negócio não dependem de frameworks, bancos ou tecnologias externas." },
  { t: "ar", q: "Qual é uma desvantagem da arquitetura hexagonal?", o: ["Pode ser “overkill” para sistemas simples", "Acopla o domínio ao banco", "Dificulta os testes do domínio", "Impede trocar de tecnologia"], e: "Estrutura inicial complexa, mais camadas e pastas e exige disciplina arquitetural." },
  { t: "ar", q: "Quem criou a Clean Architecture?", o: ["Robert C. Martin (Uncle Bob)", "Kent Beck", "Martin Fowler", "Barry Boehm"], e: "Organiza o sistema em camadas concêntricas, com as regras de negócio no centro." },
  { t: "ar", q: "Qual é a ordem das camadas da Clean Architecture, de dentro para fora?", o: ["Entities → Use Cases → Interface Adapters → Frameworks & Drivers", "Frameworks → Use Cases → Entities → Adapters", "View → Controller → Model → Database", "Ports → Adapters → Core → UI"], e: "Entities (regras de alto nível), Use Cases (orquestram), Interface Adapters (DTOs, Presenters, Gateways, Controllers), Frameworks & Drivers (DB, UI, Web)." },
  { t: "ar", q: "O que diz a Dependency Rule da Clean Architecture?", o: ["As dependências só podem apontar para dentro; o núcleo nunca depende de detalhes externos", "As dependências apontam para fora", "Toda camada depende do banco de dados", "A View deve conhecer o banco"], e: "DB, UI e HTTP viram “plugins substituíveis”." },
  { t: "ar", q: "Em qual camada da Clean Architecture ficam DTOs, Presenters, Gateways e Controllers?", o: ["Interface Adapters", "Entities", "Use Cases", "Frameworks & Drivers"], e: "Frameworks & Drivers = bancos, UI, web, frameworks, mensageria." },
  { t: "ar", q: "Qual é uma desvantagem da Clean Architecture?", o: ["Alto custo inicial e muitos arquivos/interfaces; pode ser demais para CRUDs simples", "Baixa testabilidade", "Domínio desprotegido", "Impossível trocar de banco"], e: "Também requer maturidade de design e disciplina." },
  { t: "ar", q: "Quando usar MVC?", o: ["Sistema simples ou CRUD, framework que já estrutura assim, equipe iniciante", "Domínio muito complexo com muitas integrações", "UI reativa com binding constante", "Sistema que precisa durar décadas sem depender de framework"], e: "MVVM = UI complexa/reativa; Hexagonal/Clean = domínio complexo, muitas integrações, longa vida útil." },
  { t: "ar", q: "Quando usar arquitetura hexagonal?", o: ["Domínio complexo, muitas integrações externas e software que vai evoluir por anos", "CRUD simples com equipe iniciante", "Página estática", "Quando só existe uma tela"], e: "Também quando é necessária independência de infraestrutura." },
  { t: "ar", q: "Arquiteturas relacionadas à hexagonal incluem:", o: ["Clean Architecture, Onion Architecture e DDD", "MVC e MVP apenas", "Cascata e espiral", "Scrum e Kanban"], e: "Frameworks compatíveis: Spring Boot, Quarkus, Micronaut, NestJS, FastAPI, ASP.NET Core." },

  // ======================= TESTES =======================
  { t: "te", q: "Teste de software é:", o: ["O processo de verificar e validar se o software funciona conforme o esperado", "A etapa de escrever o código", "A instalação do sistema no cliente", "A escolha da arquitetura"], e: "Busca identificar defeitos antes da entrega, garantindo RF e RNF com qualidade e confiabilidade." },
  { t: "te", q: "Qual NÃO é um objetivo dos testes citado em aula?", o: ["Eliminar a necessidade de requisitos", "Detectar erros precocemente", "Evitar retrabalho", "Aumentar a confiança na entrega"], e: "Objetivos: detectar erros cedo, evitar retrabalho, melhorar a manutenção e aumentar a confiança." },
  { t: "te", q: "Testes de caixa-branca:", o: ["Avaliam a estrutura interna do código (cobertura, caminhos lógicos)", "Avaliam só a interface, sem ver o código", "São feitos apenas pelo cliente", "Não usam código"], e: "Feitos por desenvolvedores. Caixa-preta = funcionalidade sem conhecer o código." },
  { t: "te", q: "Testes de caixa-preta:", o: ["Avaliam a funcionalidade sem conhecer o código", "Medem a cobertura de código", "Analisam caminhos lógicos internos", "Só existem em C#"], e: "Feitos por testadores/QA: interface, requisitos, comportamento." },
  { t: "te", q: "Teste de caixa-cinza é:", o: ["Uma combinação, com conhecimento parcial da estrutura interna", "Um teste sem nenhum conhecimento do sistema", "Um teste apenas de desempenho", "O mesmo que smoke test"], e: "Mistura caixa-branca e caixa-preta." },
  { t: "te", q: "Teste unitário:", o: ["Testa partes isoladas do código (funções, classes), de forma rápida e automatizada", "Testa o sistema inteiro em produção", "É sempre manual", "Verifica se vários módulos funcionam juntos"], e: "Fica em uma camada isolada do projeto para testes." },
  { t: "te", q: "Teste de integração:", o: ["Verifica se diferentes módulos funcionam juntos", "Testa uma única função isolada", "É feito antes de escrever qualquer código", "Só verifica a interface gráfica"], e: "Avalia arquitetura, desacoplamento e manutenibilidade." },
  { t: "te", q: "Teste de regressão serve para:", o: ["Garantir que novas mudanças não quebraram o que já funcionava", "Testar o desempenho com mil usuários", "Navegar livremente buscando falhas", "Checar rapidamente se o sistema sobe"], e: "No XP, os testes de unidade automatizados são usados para regressão." },
  { t: "te", q: "Smoke test é:", o: ["Uma checagem rápida de estabilidade", "Um teste exaustivo de todas as funções", "Um teste de segurança contra invasão", "O teste de aceitação do cliente"], e: "Ver se o básico funciona antes de testes mais profundos." },
  { t: "te", q: "Teste exploratório é aquele em que:", o: ["O testador navega livremente buscando falhas", "Tudo é roteirizado com antecedência", "Só se mede cobertura", "O cliente escreve o código"], e: "Por propósito: funcional, não funcional, regressão, smoke e exploratório." },
  { t: "te", q: "Testes não funcionais avaliam:", o: ["Desempenho, segurança e usabilidade", "Apenas se o botão salva o cadastro", "Somente a cobertura de código", "A ordem das sprints"], e: "Funcional = o que o sistema faz; não funcional = como (qualidade)." },
  { t: "te", q: "TDD (Test-Driven Development) é:", o: ["Escrever testes automatizados ANTES do código funcional", "Escrever testes só no fim do projeto", "Testar manualmente em produção", "Um modelo de arquitetura"], e: "O código nasce para passar nos testes; cada funcionalidade começa com um teste que falha." },
  { t: "te", q: "Qual é a ordem correta do ciclo do TDD?", o: ["Red → Green → Refactor", "Green → Red → Refactor", "Refactor → Red → Green", "Red → Refactor → Green"], e: "Red: teste que falha. Green: código mínimo para passar. Refactor: melhora mantendo os testes verdes. Repete." },
  { t: "te", q: "Na etapa Green do TDD, o desenvolvedor:", o: ["Escreve o código MÍNIMO para o teste passar", "Escreve um teste que falha", "Refatora o código", "Apaga os testes"], e: "Só o necessário para ficar verde; melhorar o código é na etapa Refactor." },
  { t: "te", q: "Na etapa Refactor do TDD:", o: ["Melhora-se o código mantendo todos os testes passando", "Escreve-se um teste que falha", "Remove-se a cobertura de testes", "Entrega-se direto ao cliente"], e: "Refatorar com segurança é um dos grandes benefícios do TDD." },
  { t: "te", q: "Qual é um benefício do TDD?", o: ["Cria documentação viva: os testes descrevem o comportamento", "Reduz o tempo inicial de desenvolvimento", "Dispensa refatoração", "Permite testar facilmente qualquer interface gráfica"], e: "Benefícios: qualidade desde o início, refatoração segura, design modular, menos manutenção, mais confiança." },
  { t: "te", q: "Qual é um desafio do TDD?", o: ["Aumenta o tempo inicial de desenvolvimento e exige mudança de mentalidade", "Gera mais bugs", "Impede a refatoração", "Não funciona com testes automatizados"], e: "Outros: difícil testar código mal projetado, exige boa cobertura e nem tudo é testável via TDD (ex.: interface gráfica)." },
  { t: "te", q: "Quais frameworks de teste são de C#?", o: ["xUnit, NUnit e MSTest", "JUnit e TestNG", "pytest e unittest", "Jest e Mocha"], e: "Java: JUnit/TestNG; Python: pytest/unittest; JavaScript: Jest/Mocha; Ruby: RSpec." },
  { t: "te", q: "Jest e Mocha são frameworks de teste de qual linguagem?", o: ["JavaScript", "Python", "Java", "Ruby"], e: "Ruby usa RSpec; Python, pytest/unittest." },
  { t: "te", q: "No xUnit, o atributo [Theory] indica:", o: ["Um teste com vários casos de entrada", "Um teste simples, sem parâmetros", "Um teste ignorado", "Uma classe de configuração"], e: "[Fact] = teste simples; [Theory] = vários casos de entrada (ex.: com InlineData)." },
  { t: "te", q: "No padrão AAA, a linha “var resultado = calc.Somar(2,3);” é a etapa:", o: ["Act", "Arrange", "Assert", "Refactor"], e: "Arrange: var calc = new Calculadora(); Act: calc.Somar(2,3); Assert: Assert.Equal(5, resultado)." },
  { t: "te", q: "No padrão AAA, “Arrange” significa:", o: ["Preparar o ambiente e os dados", "Executar a ação testada", "Verificar o resultado", "Refatorar o código"], e: "Arrange = preparar; Act = executar; Assert = verificar." },
  { t: "te", q: "Para evitar dependências externas nos testes, recomenda-se:", o: ["Usar mocks e stubs", "Testar sempre contra o banco de produção", "Desligar os testes", "Escrever testes enormes e dependentes"], e: "Boas práticas: testes pequenos e independentes, nomes descritivos, automáticos e rápidos, mocks/stubs, TDD integrado ao CI/CD." },
];

const FLASHCARDS = [
  ["Definição de engenharia de software (IEEE)", "Aplicação de uma abordagem <b>sistemática, disciplinada e quantificável</b> no desenvolvimento, operação e manutenção de software."],
  ["Base (pedra fundamental) da engenharia de software", "O <b>foco na qualidade</b>. A camada de <b>processos</b> é a “liga” que une métodos e ferramentas."],
  ["Essência da prática (4 passos)", "1) Compreender o problema · 2) Planejar a solução · 3) Executar o plano · 4) Examinar o resultado (testes/SQA)."],
  ["Os 7 princípios de Hooker", "Razão de existir · KISS · Mantenha a visão · O que um produz, outros consomem · Aberto para o futuro · Planeje a reutilização · Pense!"],
  ["KISS", "<b>Keep It Simple, Stupid</b>: o mais simples possível, mas <b>não simplista</b>."],
  ["Princípio em que todos se apoiam", "<b>A razão de existir</b>: o software existe para agregar valor ao usuário."],
  ["Processo de software", "Conjunto estruturado de atividades para desenvolver, manter e entregar software. Define <b>como, quem, quando e com quais recursos</b>."],
  ["Caso Winburg: por que fracassou?", "RNF não atendidos: precisão &lt; 98% e resposta &gt; 1 s, sem testes rigorosos → filas, cédulas válidas recusadas e papel falso aceito."],
  ["Falso positivo × falso negativo (Winburg)", "<b>Falso positivo</b>: aceitar papel falso (perda de receita). <b>Falso negativo</b>: recusar cédula válida (afasta usuários)."],
  ["Modelo cascata", "Sequencial linear, cada fase depende da anterior. Para <b>requisitos estáveis</b>. Fraco em mudanças e com <b>validação tardia</b>."],
  ["Modelo V", "Extensão do cascata: cada fase tem um teste correspondente (<b>verificação e validação</b>)."],
  ["Modelo incremental", "Entrega o software em <b>partes</b>; cascata aplicado de forma iterativa."],
  ["Modelo espiral", "Cada fase é precedida por <b>análise de riscos</b>. Raio = custo acumulado; ângulo = progresso."],
  ["Prototipagem rápida", "Protótipo = modelo operacional equivalente a um <b>subconjunto</b> do produto. O cliente valida e só então vem a especificação."],
  ["RAD", "Rapid Application Development: <b>velocidade</b>, protótipos e entregas rápidas."],
  ["Manutenção corretiva × aperfeiçoamento × adaptativa", "Corretiva: corrigir defeitos · Aperfeiçoamento: nova funcionalidade · Adaptativa: portar para novo ambiente."],
  ["Software aberto: 2 fases informais", "1) Uma pessoa cria e distribui a versão inicial · 2) Usuários viram <b>codesenvolvedores</b>."],
  ["Sincronizar-e-estabilizar", "Microsoft. 3–4 incorporações por prioridade; equipes em paralelo <b>sincronizam diariamente</b> e <b>estabilizam</b> (congelam) no fim de cada incorporação."],
  ["Objetivo do levantamento de necessidades", "Determinar <b>qual software o cliente precisa</b>. 1º passo: conhecer o campo de aplicação."],
  ["Levantamento × análise", "Levantamento descobre o conjunto preliminar; <b>análise</b> refina e estende."],
  ["Modelo de negócio", "Descrição dos processos de negócio da organização (com UML). Ex.: banco: depósitos, empréstimos, investimentos."],
  ["Entrevista estruturada × livre", "<b>Estruturada</b>: perguntas planejadas, fechadas. <b>Livre</b>: perguntas surgem das respostas."],
  ["Observação por vídeo", "Exige <b>autorização por escrito</b> dos observados."],
  ["Após a entrevista", "Relatório escrito + <b>cópia para o entrevistado</b> esclarecer ou complementar."],
  ["Ator × retângulo no caso de uso", "<b>Ator</b>: externo ao sistema (papel). <b>Retângulo</b>: o produto de software. Ex.: Customer, Teller → Withdraw Money."],
  ["Documento de especificação", "<b>Contrato</b> cliente × desenvolvedor. Componente vital: <b>critérios de aceitação</b>."],
  ["RF × RNF", "<b>RF</b> = O QUE o sistema faz (login, CRUD, pagamento). <b>RNF</b> = COMO faz (desempenho, segurança, usabilidade…)."],
  ["6 tipos de RNF da aula", "Desempenho · Usabilidade · Segurança · Confiabilidade · Escalabilidade · Portabilidade."],
  ["Filosofia ágil", "Satisfação do cliente, entrega incremental antecipada, equipes pequenas e motivadas, artefatos mínimos, <b>simplicidade</b>."],
  ["Artefato mais importante no ágil", "Um <b>incremento de software operacional</b> entregue na data. Documentos-chave: histórias de usuário e casos de teste."],
  ["Agilidade envolve", "Velocidade · Adaptação · Qualidade · Colaboração."],
  ["Time Scrum", "Product Owner + Scrum Master + devs (<b>3 a 6</b>), interdisciplinar e auto-organizado."],
  ["Artefatos do Scrum", "Backlog do produto · Backlog do sprint · Incremento."],
  ["Duração do sprint", "<b>2 a 4 semanas</b> (um slide do backlog cita 3 a 4)."],
  ["Quem encerra ou estende o sprint?", "<b>Somente o Product Owner.</b>"],
  ["Devs podem incluir tarefas no meio do sprint?", "<b>Não</b>, sem cancelar ou reiniciar o sprint."],
  ["Papel do Scrum Master", "Facilitador: conduz a daily, <b>remove obstáculos</b>, ajuda o PO com o backlog."],
  ["Daily Scrum", "<b>15 min</b>. O que fiz? Que obstáculos tenho? O que farei? Obrigatórios: SM + devs."],
  ["Retrospectiva", "Até <b>3 h</b> (sprint de 4 semanas). O que deu certo · o que melhorar · compromisso. Liderada pelo SM."],
  ["XP: 4 atividades", "Planejamento (histórias, velocidade) · Projeto (KISS, CRC, refatoração) · Codificação (TDD, pares, CI) · Testes (unidade automatizados, aceitação do cliente)."],
  ["Kanban", "Quadro visual: tarefas se movem por colunas (A fazer → Fazendo → Feito)."],
  ["MVC", "<b>Model</b> (regras/dados) · <b>View</b> (UI) · <b>Controller</b> (coordena). Risco: God Controller."],
  ["MVVM", "Model · View · <b>ViewModel</b> com <b>data binding</b>. Alta testabilidade; binding dificulta depuração."],
  ["Hexagonal (Ports and Adapters)", "Domínio no centro; <b>ports</b> = interfaces; <b>adapters</b> = implementações externas. Inversão de dependência."],
  ["Camadas da Clean Architecture", "Entities → Use Cases → Interface Adapters → Frameworks &amp; Drivers (de dentro para fora)."],
  ["Dependency Rule", "Dependências <b>só apontam para dentro</b>; o núcleo nunca depende de detalhes."],
  ["Quando usar MVC × MVVM × Hexagonal", "MVC: simples/CRUD · MVVM: UI reativa/complexa · Hexagonal/Clean: domínio complexo, muitas integrações, vida longa."],
  ["Caixa-branca × preta × cinza", "Branca: estrutura interna (devs) · Preta: funcionalidade sem ver código (QA) · Cinza: conhecimento parcial."],
  ["Unitário × integração", "<b>Unitário</b>: parte isolada, rápido · <b>Integração</b>: módulos funcionando juntos."],
  ["Regressão · smoke · exploratório", "Regressão: mudanças não quebraram nada · Smoke: checagem rápida · Exploratório: navegar livremente buscando falhas."],
  ["Ciclo TDD", "<b>Red</b> (teste falha) → <b>Green</b> (código mínimo) → <b>Refactor</b> (melhora mantendo verde)."],
  ["Frameworks de teste", "C#: xUnit, NUnit, MSTest · Java: JUnit, TestNG · Python: pytest, unittest · JS: Jest, Mocha · Ruby: RSpec."],
  ["[Fact] × [Theory] (xUnit)", "<b>[Fact]</b>: teste simples · <b>[Theory]</b>: vários casos de entrada."],
  ["Padrão AAA", "<b>Arrange</b> (preparar) · <b>Act</b> (executar) · <b>Assert</b> (verificar). Ex.: Assert.Equal(5, calc.Somar(2,3))."],
];

const DISCURSIVAS = [
  // ---------- Revisão ----------
  { f: "Revisão – Fundamentos 1", t: "fu", q: "Defina engenharia de software segundo o IEEE e explique a visão em camadas (qualidade, processo, métodos, ferramentas).",
    r: "<p><b>IEEE:</b> aplicação de uma abordagem <b>sistemática, disciplinada e quantificável</b> no desenvolvimento, na operação e na manutenção de software — a aplicação de engenharia ao software.</p><p><b>Camadas:</b> a base (pedra fundamental) é o <b>foco na qualidade</b>. Acima dela, a camada de <b>processos</b> é a liga que mantém tudo coeso e permite desenvolver de forma racional e no prazo. Depois vêm os <b>métodos</b> (como fazer: comunicação, análise, projeto, código, testes) e as <b>ferramentas</b> (apoio automatizado).</p>",
    k: ["Sistemática, disciplinada e quantificável", "Desenvolvimento, operação e manutenção", "Qualidade é a base", "Processo é a liga entre as camadas"] },
  { f: "Revisão – Fundamentos 2", t: "fu", q: "Cite e explique os sete princípios de Hooker.",
    r: "<ol><li><b>A razão de existir</b>: agregar valor ao usuário; base de todos.</li><li><b>KISS</b>: o mais simples possível, mas não simplista.</li><li><b>Mantenha a visão</b>: integridade conceitual, sem colcha de retalhos.</li><li><b>O que um produz, outros consomem</b>: alguém vai manter seu código.</li><li><b>Esteja aberto para o futuro</b>: projetar para mudanças (“e se…?”).</li><li><b>Planeje com antecedência a reutilização</b>: reduz custo; a meta mais difícil.</li><li><b>Pense!</b>: pensar antes de agir; reconhecer o que não se sabe.</li></ol>",
    k: ["Razão de existir (valor)", "KISS", "Mantenha a visão", "O que um produz, outros consomem", "Aberto para o futuro", "Reutilização", "Pense"] },
  { f: "Revisão – Fundamentos 3", t: "fu", q: "Explique o caso Winburg: o que o sistema deveria fazer, por que fracassou e qual lição ele traz para a engenharia de software.",
    r: "<p>Ônibus com máquina que aceita só cédulas de $1, validadas por <b>reconhecimento de imagem</b>. Requisitos: <b>precisão ≥ 98%</b> e <b>resposta &lt; 1 s</b>.</p><p><b>Fracasso:</b> precisão abaixo de 98% (cédulas válidas recusadas = falsos negativos; papel falso aceito = falsos positivos), validação lenta (filas no pico), RNF críticos não considerados, <b>falta de testes rigorosos</b> e desconsideração da experiência do usuário.</p><p><b>Lição:</b> requisitos não funcionais podem decidir o sucesso; precisam ser especificados, medidos e testados antes da implantação.</p>",
    k: ["Precisão ≥ 98% e < 1 s", "Falso positivo × falso negativo", "RNF não atendidos", "Falta de testes", "Rejeição pelos usuários"] },
  { f: "Revisão – Ciclo de vida 1", t: "ci", q: "Compare os modelos cascata, incremental, espiral e prototipagem rápida: característica principal, vantagem e quando usar.",
    r: "<ul><li><b>Cascata</b>: sequencial e rígido; simples e previsível; requisitos estáveis e ambientes regulados. Fraco: validação tardia.</li><li><b>Incremental</b>: entregas parciais; feedback rápido; quando dá para priorizar funções e entregar aos poucos.</li><li><b>Espiral</b>: ciclos com <b>análise de riscos</b>; ótimo para projetos grandes e arriscados.</li><li><b>Prototipagem</b>: protótipo validado pelo cliente antes da especificação; quando os requisitos são incertos.</li></ul>",
    k: ["Cascata: sequencial, requisitos estáveis", "Incremental: entregas parciais", "Espiral: riscos", "Prototipagem: requisitos incertos"] },
  { f: "Revisão – Ciclo de vida 2", t: "ci", q: "Descreva o modelo sincronizar-e-estabilizar e o modelo de software aberto, citando os tipos de manutenção.",
    r: "<p><b>Sincronizar-e-estabilizar</b> (Microsoft): entrevistas com futuros clientes → lista de recursos prioritários → especificação → 3 ou 4 <b>incorporações</b> por prioridade, com pequenas equipes em paralelo. No fim de cada dia as equipes <b>sincronizam</b> (integram, testam, depuram); no fim de cada incorporação <b>estabilizam</b> (corrigem e congelam).</p><p><b>Software aberto</b>: 1) uma pessoa cria e distribui a versão inicial; 2) usuários viram codesenvolvedores. Trabalho voluntário, com grupo central de mantenedores e grupo periférico. Manutenção <b>corretiva</b> (defeitos), <b>de aperfeiçoamento</b> (novas funções) e <b>adaptativa</b> (novo ambiente).</p>",
    k: ["Sincronização diária", "Estabilização por incorporação", "Duas fases informais", "Corretiva/aperfeiçoamento/adaptativa"] },
  { f: "Revisão – Requisitos 1", t: "rq", q: "Explique o fluxo de levantamento de necessidades: domínio, modelo de negócio, entrevistas, observação e iteração.",
    r: "<p>1) <b>Conhecer o campo de aplicação</b>. 2) Construir o <b>modelo de negócio</b> (processos do cliente em UML). 3) Usá-lo para elaborar o conjunto <b>preliminar</b> de necessidades. 4) <b>Iterar</b>: entender melhor o domínio → refinar o modelo → refinar as necessidades (isso é a <b>análise</b>).</p><p>Técnicas: entrevistas <b>estruturadas</b> (perguntas fechadas, planejadas) e <b>livres</b>; <b>observação direta</b> e vídeo (com autorização por escrito); <b>relatório</b> com cópia ao entrevistado.</p>",
    k: ["Campo de aplicação primeiro", "Modelo de negócio em UML", "Iteração/refinamento", "Estruturada × livre", "Autorização por escrito", "Relatório com cópia"] },
  { f: "Revisão – Requisitos 2", t: "rq", q: "Diferencie requisitos funcionais e não funcionais, com dois exemplos de cada, e explique o papel do documento de especificação.",
    r: "<p><b>RF (O QUE)</b>: ações visíveis ao usuário. Ex.: “o sistema deve permitir login com usuário e senha”; “o sistema deve exibir o histórico de pedidos”.</p><p><b>RNF (COMO)</b>: atributos de qualidade e restrições que influenciam a arquitetura. Ex.: “transação em menos de 3 s” (desempenho); “senhas criptografadas” (segurança); “99,9% de disponibilidade” (confiabilidade).</p><p>O <b>documento de especificação</b> é um <b>contrato</b> entre cliente e desenvolvedor; sua parte vital são os <b>critérios de aceitação</b>, testes que provam que o produto atende à especificação.</p>",
    k: ["RF = o que", "RNF = como/qualidade", "Exemplos corretos", "Especificação = contrato", "Critérios de aceitação"] },
  { f: "Revisão – Ágeis 1", t: "ag", q: "Descreva o Scrum: papéis, artefatos, eventos e as regras sobre quem pode alterar o sprint.",
    r: "<p><b>Papéis</b>: Product Owner (prioriza o backlog, define a meta), Scrum Master (facilitador, remove obstáculos), equipe de dev (3–6, auto-organizada).</p><p><b>Artefatos</b>: backlog do produto, backlog do sprint, incremento.</p><p><b>Eventos</b>: Sprint Planning; sprint de 2–4 semanas; <b>Daily</b> de 15 min (o que fiz, obstáculos, o que farei); <b>Retrospectiva</b> de até 3 h (o que deu certo, o que melhorar, compromisso).</p><p><b>Regras</b>: só o <b>PO</b> encerra ou estende o sprint; os devs não adicionam tarefas sem cancelar/reiniciar o sprint.</p>",
    k: ["PO, SM, devs 3–6", "3 artefatos", "Daily 15 min / 3 perguntas", "Retrospectiva ≤ 3 h", "Só o PO encerra/estende"] },
  { f: "Revisão – Ágeis 2", t: "ag", q: "Explique as quatro atividades do XP e suas práticas. Compare XP, Scrum e Kanban.",
    r: "<ul><li><b>Planejamento</b>: histórias de usuário do cliente, priorizadas por valor; custo em semanas; velocidade do projeto.</li><li><b>Projeto</b>: KISS, cartões CRC, protótipos para problemas difíceis, refatoração contínua.</li><li><b>Codificação</b>: testes antes do código (TDD), programação em pares, integração contínua.</li><li><b>Testes</b>: testes de unidade automatizados (regressão) e testes de aceitação do cliente.</li></ul><p><b>Scrum</b> = papéis, sprints e reuniões (gestão). <b>XP</b> = práticas técnicas. <b>Kanban</b> = quadro visual de fluxo.</p>",
    k: ["Planejamento/projeto/codificação/testes", "Histórias e velocidade", "CRC e refatoração", "Pares, TDD, CI", "Scrum gestão × XP técnica × Kanban fluxo"] },
  { f: "Revisão – Arquiteturas 1", t: "ar", q: "Compare MVC, MVVM, Hexagonal e Clean Architecture: o que é, problema que resolve e quando usar cada uma.",
    r: "<ul><li><b>MVC</b>: Model/View/Controller; separa negócio da UI; sistemas simples/CRUD e frameworks como Rails, Laravel e Django. Risco: God Controller.</li><li><b>MVVM</b>: ViewModel + data binding; UI declarativa e testável; UIs reativas, mobile e SPA (Angular, WPF, SwiftUI, Flutter).</li><li><b>Hexagonal</b>: domínio + ports + adapters; independência de infraestrutura; domínio complexo e muitas integrações.</li><li><b>Clean</b> (Uncle Bob): Entities → Use Cases → Interface Adapters → Frameworks &amp; Drivers; dependências só para dentro; sistemas de longa duração. Custo inicial alto.</li></ul>",
    k: ["MVC: 3 camadas, CRUD", "MVVM: binding, UI reativa", "Hexagonal: ports/adapters", "Clean: regra de dependência", "Quando usar cada"] },
  { f: "Revisão – Testes 1", t: "te", q: "Explique o TDD (ciclo, benefícios e desafios) e o padrão AAA com um exemplo em xUnit.",
    r: "<p><b>TDD</b>: escrever o teste antes do código. <b>Red</b> (teste falha) → <b>Green</b> (código mínimo para passar) → <b>Refactor</b> (melhorar mantendo verde), repetindo a cada funcionalidade.</p><p><b>Benefícios</b>: menos bugs, refatoração segura, design modular, documentação viva. <b>Desafios</b>: mudança de mentalidade, mais tempo inicial, código mal projetado é difícil de testar, nem tudo é testável (UI).</p><pre>[Fact]\npublic void Somar_DoisNumeros_RetornaSoma() {\n  var calc = new Calculadora();        // Arrange\n  var resultado = calc.Somar(2, 3);    // Act\n  Assert.Equal(5, resultado);          // Assert\n}</pre>",
    k: ["Teste antes do código", "Red → Green → Refactor", "Benefícios e desafios", "Arrange/Act/Assert", "[Fact]"] },
  { f: "Revisão – Testes 2", t: "te", q: "Diferencie testes de caixa-branca, caixa-preta e caixa-cinza; unitário e de integração; e os testes de regressão, smoke e exploratório.",
    r: "<ul><li><b>Caixa-branca</b>: estrutura interna (cobertura, caminhos), feito por devs. <b>Caixa-preta</b>: funcionalidade sem ver o código, feito por QA. <b>Caixa-cinza</b>: conhecimento parcial.</li><li><b>Unitário</b>: parte isolada (função/classe), rápido e automatizado. <b>Integração</b>: módulos juntos; avalia arquitetura e desacoplamento.</li><li><b>Regressão</b>: mudanças não quebraram o que funcionava. <b>Smoke</b>: checagem rápida de estabilidade. <b>Exploratório</b>: navegação livre buscando falhas.</li></ul>",
    k: ["Branca/preta/cinza", "Unitário × integração", "Regressão", "Smoke", "Exploratório"] },

  // ---------- Trabalho ----------
  { f: "Trabalho – Biblioteca 1", t: "rq", q: "Trabalho (exemplo: Sistema de Biblioteca Escolar). Liste pelo menos 5 requisitos funcionais e 3 não funcionais.",
    r: "<p><b>RF</b></p><ol><li>RF01 – O sistema deve permitir cadastrar, alterar, excluir e consultar livros (título, autor, ISBN, exemplares).</li><li>RF02 – O sistema deve permitir cadastrar usuários (alunos e professores).</li><li>RF03 – O sistema deve registrar empréstimos, com data prevista de devolução.</li><li>RF04 – O sistema deve registrar devoluções e calcular atraso/multa.</li><li>RF05 – O sistema deve permitir consultar a disponibilidade de um livro.</li><li>RF06 – O sistema deve impedir novo empréstimo para usuário com atraso.</li></ol><p><b>RNF</b></p><ol><li>RNF01 (desempenho) – a consulta deve responder em até 2 s.</li><li>RNF02 (segurança) – só bibliotecários autenticados podem registrar empréstimos; senhas criptografadas.</li><li>RNF03 (usabilidade) – um bibliotecário novo deve usar o sistema com no máximo 1 h de treinamento.</li><li>RNF04 (confiabilidade) – backup diário, sem perda de dados em queda de energia.</li></ol>",
    k: ["≥ 5 RF no formato “o sistema deve…”", "≥ 3 RNF com categoria", "RNF mensuráveis (2 s, 1 h)", "Cobre cadastro, empréstimo, devolução e consulta"] },
  { f: "Trabalho – Biblioteca 2", t: "rq", q: "Trabalho (exemplo: Biblioteca). Descreva o diagrama de casos de uso e o diagrama de classes (entidades, campos e métodos).",
    r: "<p><b>Casos de uso</b> — atores: <b>Bibliotecário</b> e <b>Usuário</b> (aluno/professor). Dentro do retângulo “Sistema de Biblioteca”: Cadastrar livro, Cadastrar usuário, Registrar empréstimo, Registrar devolução, Consultar disponibilidade, Fazer login. O Bibliotecário liga-se a todos; o Usuário a “Consultar disponibilidade”. “Registrar empréstimo” <i>inclui</i> “Consultar disponibilidade”.</p><p><b>Classes</b></p><ul><li><b>Livro</b>: isbn, titulo, autor, ano, qtdExemplares · disponivel(), atualizarEstoque()</li><li><b>Usuario</b>: id, nome, tipo, email · podeEmprestar()</li><li><b>Emprestimo</b>: id, dataEmprestimo, dataPrevista, dataDevolucao · registrar(), devolver(), calcularMulta()</li><li><b>Bibliotecario</b>: id, nome, login, senhaHash · autenticar()</li></ul><p>Associações: Usuario 1 — 0..* Emprestimo; Livro 1 — 0..* Emprestimo; Bibliotecario 1 — 0..* Emprestimo. Ferramentas: draw.io, Lucidchart, StarUML, Creately.</p>",
    k: ["Atores fora do retângulo", "Casos de uso como verbos", "Classes com campos e métodos", "Multiplicidades", "Ferramenta UML"] },
  { f: "Trabalho – Biblioteca 3", t: "ci", q: "Trabalho (exemplo: Biblioteca). Escolha um modelo clássico de ciclo de vida, mostre as fases aplicadas ao sistema e justifique.",
    r: "<p><b>Modelo escolhido: Cascata</b> (alternativa: Incremental).</p><p><b>Por quê:</b> requisitos da biblioteca são <b>bem conhecidos e estáveis</b> (cadastro, empréstimo, devolução, consulta), o escopo é pequeno e a escola precisa de documentação clara.</p><p><b>Fases:</b> 1) <b>Requisitos</b>: entrevistas com bibliotecárias e lista de RF/RNF. 2) <b>Análise e projeto</b>: casos de uso, classes, banco. 3) <b>Implementação</b> dos módulos. 4) <b>Testes</b> contra os critérios de aceitação. 5) <b>Implantação</b> e treinamento. 6) <b>Manutenção</b>.</p><p><b>Vantagens:</b> previsibilidade de prazo/custo, documentação para a escola, fácil gestão. <b>Risco</b> (validação tardia) é baixo porque os requisitos quase não mudam.</p><p><i>Se escolher Incremental:</i> 1º incremento cadastro de livros/usuários; 2º empréstimo/devolução; 3º consultas e relatórios.</p>",
    k: ["Modelo nomeado", "Justificativa ligada ao sistema", "Fases aplicadas ao sistema", "Vantagens para o projeto", "Reconhece o ponto fraco"] },
];
